(()=>{
 'use strict';
 let quote=null,bound=null,submitting=false;
 const req=async(path,body)=>{const r=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Não foi possível concluir.');return d};
 const esc=s=>String(s||'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));
 const feedback=(wrap,text,type='info')=>{const el=wrap.querySelector('#quick-feedback');if(!el)return;el.hidden=!text;el.className='quick-feedback '+type;el.textContent=text||''};
 function auto(input){const box=document.createElement('div');let timer;box.className='quick-suggestions';input.parentElement.append(box);input.oninput=()=>{quote=null;const create=document.querySelector('#quick-create');if(create)create.disabled=true;clearTimeout(timer);if(input.value.trim().length<3){box.innerHTML='';return}timer=setTimeout(async()=>{try{const d=await req('/api/delivery/address?q='+encodeURIComponent(input.value));box.innerHTML=(d.results||[]).map((x,i)=>`<button type="button" data-i="${i}">${esc(x.label)}</button>`).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{input.value=d.results[+b.dataset.i].label;box.innerHTML=''})}catch{}},350)}}
 async function open(){
  quote=null;submitting=false;
  const s=await req('/api/delivery/state'),shops=(s.members||[]).filter(x=>x.kind==='merchant'&&x.approved&&x.quick_delivery_enabled!==false);
  let wrap=document.getElementById('quick-delivery-modal');if(!wrap){wrap=document.createElement('div');wrap.id='quick-delivery-modal';wrap.className='admin-modal';document.body.append(wrap)}
  wrap.hidden=false;wrap.innerHTML=`<div class="admin-modal-card quick-delivery-card" role="dialog" aria-modal="true" aria-labelledby="quick-title"><div class="section-title"><div><p class="eyebrow">SOLICITAÇÃO RÁPIDA</p><h3 id="quick-title">Chamar entregador</h3></div><button type="button" data-close aria-label="Fechar">&times;</button></div><form id="quick-delivery-form" class="admin-form"><label>Local de coleta<select name="merchant" required><option value="">Escolha um estabelecimento</option>${shops.map(x=>`<option value="${x.user_id}">${esc(x.name)} · ${esc(x.address)}</option>`).join('')}</select></label><label class="quick-wide">Endereço de entrega<input name="destination" required minlength="5" autocomplete="off" placeholder="Rua, número, bairro e cidade"></label><label>Nome do cliente<input name="recipient" required></label><label>Telefone do cliente<input name="phone" required></label><label>Forma de pagamento<select name="payment_method"><option value="wallet">Carteira de créditos</option><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="credit">Cartão</option></select></label><label>Número do pedido<input name="external_order_number"></label><div id="quick-quote" class="quick-quote">A coleta usará automaticamente o endereço cadastrado da loja.</div><div id="quick-feedback" class="quick-feedback" role="status" hidden></div><div class="quick-buttons"><button type="button" id="quick-estimate">Calcular valor</button><button class="primary" id="quick-create" disabled>Solicitar entrega</button></div></form></div>`;
  const close=()=>{if(!submitting)wrap.hidden=true};wrap.querySelector('[data-close]').onclick=close;wrap.onclick=e=>{if(e.target===wrap)close()};
  const f=wrap.querySelector('form'),estimate=wrap.querySelector('#quick-estimate'),create=wrap.querySelector('#quick-create');auto(f.destination);
  for(const field of [f.merchant,f.destination])field.addEventListener('change',()=>{quote=null;create.disabled=true;feedback(wrap,'')});
  estimate.onclick=async()=>{estimate.disabled=true;feedback(wrap,'Calculando rota…');try{quote=await req('/api/delivery/quote',{merchant:f.merchant.value,destination:f.destination.value});wrap.querySelector('#quick-quote').innerHTML=`<b>${(quote.distance_m/1000).toFixed(2).replace('.',',')} km · ${(quote.price_cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</b><br>Endereço confirmado: ${esc(quote.destination)}`;create.disabled=false;feedback(wrap,'Rota e valor confirmados.','success')}catch(e){feedback(wrap,e.message,'error')}finally{estimate.disabled=false}};
  f.onsubmit=async e=>{e.preventDefault();if(!quote||submitting)return;submitting=true;create.disabled=true;create.textContent='Criando entrega…';feedback(wrap,'Registrando e enviando para o despacho…');const d=Object.fromEntries(new FormData(f));d.quote_id=quote.id;try{const created=await req('/api/delivery/action',{action:'admin_create',data:d});feedback(wrap,'Entrega criada com sucesso.','success');window.dispatchEvent(new CustomEvent('vuppi:delivery-created',{detail:created}));setTimeout(()=>{wrap.hidden=true;submitting=false},500)}catch(x){feedback(wrap,x.message,'error');submitting=false;create.disabled=false;create.textContent='Solicitar entrega'}};
 }
 let augmenting=false;async function augmentMerchants(){if(augmenting||!document.querySelector('#member-list'))return;augmenting=true;try{const st=await req('/api/delivery/state');for(const card of document.querySelectorAll('#member-list .member-card')){if(card.querySelector('[data-quick-delivery]'))continue;const name=card.querySelector('h3')?.textContent.trim(),m=(st.members||[]).find(x=>x.kind==='merchant'&&x.name===name);if(!m)continue;const label=document.createElement('label');label.className='quick-enable';label.innerHTML='<input type="checkbox" data-quick-delivery '+(m.quick_delivery_enabled!==false?'checked':'')+'> Solicitação rápida';label.querySelector('input').onchange=async e=>{try{await req('/api/delivery/action',{action:'quick_delivery',data:{id:m.user_id,enabled:e.target.checked}})}catch(x){e.target.checked=!e.target.checked;alert(x.message)}};card.querySelector('.member-actions')?.append(label)}}finally{augmenting=false}}
 function bind(){const a=document.querySelector('.request-delivery');if(a&&a!==bound){bound=a;a.removeAttribute('href');a.removeAttribute('target');a.style.cursor='pointer';a.onclick=e=>{e.preventDefault();open().catch(x=>window.dispatchEvent(new CustomEvent('vuppi:admin-error',{detail:x.message})))}}augmentMerchants()}
 new MutationObserver(bind).observe(document.body,{childList:true,subtree:true});bind();
})();
